formData.jsFunction:
def valid(response, elementCheck, keyName, regexMap = [:]) {
    def validString = regexMap?.aliasName
    if (!validString) {
        response.invalidString = " regex 'aliasName' is not configured in regex.properties"
        return false
    }
    if (!elementCheck.matches(validString)) {
        response.invalidString = " " + keyName + ' contains invalid characters. only .$()[]\'_-* allowed'
        return false
    }
    if (elementCheck.startsWith(" ")) {
        response.invalidString = " " + keyName + " should not start with space"
        return false
    }

    if (elementCheck.length() > 100) {
        response.invalidString = " " + keyName + " should not be more than 100 characters"
        return false
    }

    return true
}

def validate(request, response = [:], regexMap = [:]) {

    if (!request?.uuid) {
        response.uuid = "The required uuid in the formData is missing"
        return response
    }
    if (!(request.expression instanceof List)) {
        response.expression = "The required 'expression' array in the formData is missing"
        return response
    }
    def expressionArray = request.expression

    if (expressionArray.size() == 0) {
        response.expression = "The required 'expression' array  in formData should not be empty"
        return response
    }

    for (expressionJson in expressionArray) {

        if (!(
                expressionJson.containsKey("action")
                        && expressionJson.containsKey('on')
                        && expressionJson.containsKey("executionType")
                        && expressionJson.containsKey("expressionName")
                        && expressionJson.containsKey("accessType")
                        && expressionJson.containsKey("expressionType")
                        && expressionJson.containsKey("condition")
        )) {
            response.expression = "The required key  'action', 'expressionType', 'on', 'executionType', 'accessType','expressionName', 'condition' in formData is missing "
            return response
        }

        if (!(
                expressionJson.action instanceof String
                        && expressionJson.executionType instanceof String
                        && expressionJson.expressionName instanceof String
                        && expressionJson.accessType instanceof String
                        && expressionJson.expressionType instanceof String
                        && expressionJson.condition instanceof String
        )) {
            response.expression = "The required key  'action', 'expressionType',  'executionType', 'accessType','expressionName', 'condition' should be of String type"
            return response
        }

        def maliciousCode = "Malicious code 'System' class detected"

        def system = "System"
        if ((
                expressionJson.action.isEmpty()
                        || expressionJson.executionType.isEmpty()
                        || expressionJson.expressionName.isEmpty()
                        || expressionJson.accessType.isEmpty()
                        || expressionJson.expressionType.isEmpty()
                        || expressionJson.condition.isEmpty()
        )) {
            response.expression = "The required key  'action', 'expressionType',  'executionType', 'accessType','expressionName', 'condition' should not be empty"
            return response
        } else {
            if (!(
                    valid(response, expressionJson.executionType, "executionType", regexMap) &&
                            valid(response, expressionJson.expressionName, "expressionName", regexMap) &&
                            valid(response, expressionJson.accessType, "accessType", regexMap) &&
                            valid(response, expressionJson.expressionType, "expressionType", regexMap)
            )) {

                return response

            }
            if (expressionJson.accessType.contains("grant")) {
                if (!expressionJson.containsKey("filter")) {
                    response.filter = "The filter key is required when grant is selected"
                    return response
                }

                if (expressionJson.filter.isEmpty()) {
                    response.filter = "The filter should not be empty"

                    return response
                }
            }

            if (expressionJson.condition.contains(system)) {
                response.condition = maliciousCode
                return response
            }

            def action = expressionJson.action
            if (expressionJson.containsKey("expressionId")) {
                if (!"edit".equalsIgnoreCase(action)) {
                    response.expression = "Expected action 'edit' with the expression that has 'expressionId'"
                    return response
                }
                if (!valid(response, expressionJson.expressionId, "expressionId", regexMap)) {
                    return response
                }
            } else {
                if (!"add".equalsIgnoreCase(action)) {
                    response.expression = "Expected action 'add' with the expression that has no 'expressionId'"
                    return response
                }

            }

            if (!(expressionJson.on instanceof List)) {
                response.on = "Expected 'on' key value should be an array"
                return response

            }
            if (expressionJson.on.size() == 0) {
                response.on = "Expected 'on' array should not be empty"
                return response
            }


            for (onElement in expressionJson.on) {
                def entity = onElement
                if (entity.isEmpty()) {
                    response.on = "One of the on values are empty"
                    return response
                }

                if (!valid(response, entity, "on", regexMap)) {
                    return response
                }

                //if ("column".equalsIgnoreCase(expressionJson.expressionType) && !entity.contains(".")) {
                //    response.on = "Columns " + entity + " has no table information. Hint: Column names should have table name separated by dot (.) "
                //    return response
                //}

                if (!valid(response, entity, "on", regexMap)) {
                    return response
                }
            }

        }

        if (expressionJson.containsKey("filter") && expressionJson.filter?.contains(system)) {
            response.condition = maliciousCode
            return response
        }

        return response
    }

    return response
}
